GEN3_JP_KANA = '?あいうえおかきくけこさしすせそたちつてとなにぬねのはひふへほまみむめもやゆよらりるれろわをんぁぃぅぇぉゃゅょがぎぐげござじずぜぞだぢづでどばびぶべぼぱぴぷぺぽっアイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲンァィゥェォャュョガギグゲゴザジズゼゾダヂヅデドバビブベボパピプペポッ'


def gen3_jp_text(raw):
    """Japanese Gen 3 text up to its 0xFF end mark (kana, digits, the long-vowel mark)."""
    out = []
    for b in raw.split(b"\xFF")[0]:
        out.append(GEN3_JP_KANA[b] if 0 < b < 0xA1 else str(b - 0xA1) if b < 0xAB else
                   {0x00: " ", 0xAB: "!", 0xAC: "?", 0xAD: "。", 0xAE: "ー"}.get(b, "?"))
    return "".join(out)


def pk3_species(internal):
    """(National Dex number, name) for a Gen 3 internal species number (Hoenn's are reordered)."""
    if 1 <= internal <= 251:
        n = internal
    elif 277 <= internal <= 411:
        n = PK3_HOENN_TO_NATIONAL[internal - 277]
    elif internal == 412:
        return 0, "EGG"
    else:
        return 0, f"species {internal}"
    return n, PK3_NAMES.split("|")[n - 1]


def parse_pk3(data):
    """A Gen 3 Pokemon (.pk3, 80 or 100 bytes): returns (fields, problems). Raises ValueError if it
    isn't one."""
    if len(data) not in (80, 100):
        raise ValueError(f"not a Gen 3 Pokemon: {len(data)} bytes, not 80 (box) or 100 (party)")
    pid, otid = struct.unpack_from("<II", data, 0)
    stored = struct.unpack_from("<H", data, 0x1C)[0]
    problems = []
    as_is = data[0x20:0x50]
    key = pid ^ otid
    decrypted = struct.pack("<12I", *[w ^ key for w in struct.unpack_from("<12I", data, 0x20)])
    if sum(struct.unpack("<24H", as_is)) & 0xFFFF == stored:
        form, plain, order = "PKHeX's (decrypted)", as_is, "GAEM"          # what PKHeX saves
    else:
        form, plain, order = "the game's (encrypted)", decrypted, PK3_ORDERS[pid % 24]
        total = sum(struct.unpack("<24H", plain)) & 0xFFFF
        if total != stored:
            problems.append(f"its checksum is {stored:#06x}, but its data adds up to {total:#06x} "
                            "(decrypted) or isn't stored decrypted either")
    block = {c: plain[12 * i:12 * i + 12] for i, c in enumerate(order)}
    species, item, exp = struct.unpack_from("<HHI", block["G"], 0)
    evs = list(block["E"][0:6])                       # HP, Attack, Defense, Speed, Sp. Atk, Sp. Def
    moves = struct.unpack_from("<4H", block["A"], 0)
    pokerus, met, origins, ivs, ribbons = struct.unpack_from("<BBHII", block["M"], 0)
    lang = data[0x12]
    text = gen3_jp_text if lang == 1 else gen3_text
    dex, name = pk3_species(species)
    if not species:
        problems.append("it has no species")
    return dict(pid=pid, tid=otid & 0xFFFF, sid=otid >> 16, nickname=text(data[0x08:0x12]),
                ot=text(data[0x14:0x1B]), language=GAME_LANGUAGES.get(lang, f"language {lang}"),
                species=species, dex=dex, name=name, item=item, exp=exp, moves=[m for m in moves if m],
                met_location=met, met_level=origins & 0x7F, game=PK3_GAMES.get(origins >> 7 & 0xF, f"game {origins >> 7 & 0xF}"),
                ball=PK3_BALLS.get(origins >> 11 & 0xF, f"ball {origins >> 11 & 0xF}"),
                ot_gender="female" if origins >> 15 else "male", egg=bool(ivs >> 30 & 1),
                ivs=[ivs >> (5 * i) & 31 for i in range(6)], evs=evs, ribbons=ribbons & 0x7FFFFFFF,
                fateful=bool(ribbons >> 31), shiny=((otid >> 16) ^ (otid & 0xFFFF) ^ (pid >> 16) ^ (pid & 0xFFFF)) < 8,
                party=len(data) == 100, form=form, blocks=b"".join(block[c] for c in "GAEM")), problems


def pk3_game_form(data):
    """A .pk3 in the game's own form (encrypted, blocks shuffled), as a trade would carry it."""
    f, problems = parse_pk3(data)
    if problems:
        raise ValueError("; ".join(problems))
    plain = b"".join(f["blocks"][12 * "GAEM".index(c):12 * "GAEM".index(c) + 12] for c in PK3_ORDERS[f["pid"] % 24])
    key = struct.unpack_from("<I", data, 0)[0] ^ struct.unpack_from("<I", data, 4)[0]
    enc = struct.pack("<12I", *[w ^ key for w in struct.unpack("<12I", plain)])
    return data[:0x20] + enc + data[0x50:]


# A trade carries each Pokemon in the game's 100-byte party form, and Ruby keeps the party fields
# as they arrive (trade.c swaps the structs; it never recalculates them). So the level, HP and
# stats must be right: worked out here as pokemon.c does, from the species' base stats and growth
# rate (pokeemerald species_info.h, internal species order, 7 bytes each, zlib + base64), the
# experience tables (experience_tables.h), the IVs, EVs and nature.
PK3_BASE_STATS = zlib.decompress(__import__("base64").b64decode(
    ""))


def pk3_exp_for_level(growth, n):
    """gExperienceTables: the experience a Pokemon needs for level n."""
    if n <= 1:
        return n
    c = n * n * n
    if growth == 0:
        return c
    if growth == 1:
        return ((100 - n) * c // 50 if n <= 50 else (150 - n) * c // 100 if n <= 68 else
                ((1911 - 10 * n) // 3) * c // 500 if n <= 98 else (160 - n) * c // 100)
    if growth == 2:
        return (((n + 1) // 3 + 24) * c // 50 if n <= 15 else (n + 14) * c // 50 if n <= 36 else
                ((n // 2) + 32) * c // 50)
    if growth == 3:
        return 6 * c // 5 - 15 * n * n + 100 * n - 140
    return 4 * c // 5 if growth == 4 else 5 * c // 4


def pk3_party_fields(f):
    """The 20 bytes after the box data: status, level, mail, HP, max HP, Attack, Defense, Speed,
    Sp. Atk, Sp. Def (pokemon.c CalculateMonStats)."""
    species = f["species"]
    if not (1 <= species <= 411) or species == 412:
        raise ValueError(f"no stats for species {species}")
    base = PK3_BASE_STATS[(species - 1) * 7:(species - 1) * 7 + 7]
    level = 1
    while level < 100 and f["exp"] >= pk3_exp_for_level(base[6], level + 1):
        level += 1
    ivs, evs = f["ivs"], f["evs"]
    nature = f["pid"] % 25
    stats = []
    for i in range(6):
        n = (2 * base[i] + ivs[i] + evs[i] // 4) * level // 100
        if i == 0:
            stats.append(1 if species == 303 else n + level + 10)     # 303: Shedinja (internal)
            continue
        n += 5
        k = i - 1                                                      # Attack, Defense, Speed, Sp. Atk, Sp. Def
        if nature // 5 != nature % 5:
            if nature // 5 == k:
                n = n * 110 // 100
            elif nature % 5 == k:
                n = n * 90 // 100
        stats.append(n)
    hp, atk, de, spe, spa, spd = stats
    return struct.pack("<IBBHHHHHHH", 0, level, 0xFF, hp, hp, atk, de, spe, spa, spd)


def pk3_party_form(data):
    """A .pk3 as a trade carries it: the game's encrypted box data, then the party fields, worked
    out (or kept, from a 100-byte file that has them)."""
    f, problems = parse_pk3(data)
    box = pk3_game_form(data[:80])
    if len(data) == 100 and any(data[84:100]):
        return box + data[80:100]
    return box + pk3_party_fields(f)


def describe_pk3(f):
    """One line or two about a Pokemon, for pk3-info."""
    met = ("a fateful encounter" if f["met_location"] == PK3_MET_FATEFUL else
           "an in-game trade" if f["met_location"] == PK3_MET_TRADE else f"location {f['met_location']}")
    return (f"#{f['dex']:03d} {f['name']}{' (egg)' if f['egg'] else ''}{' (shiny)' if f['shiny'] else ''}, "
            f"\"{f['nickname']}\", OT {f['ot']} ({f['ot_gender']}) {f['tid']:05d}/{f['sid']:05d}, {f['language']}; "
            f"from {f['game']}, met at {met} (level {f['met_level']}), {f['ball']} Ball"
            + ("; marked as an official event (fateful encounter)" if f["fateful"] else "")
            + f"; stored in {f['form']} form")


def pk3_info(paths):
    for p in paths:
        try:
            f, problems = parse_pk3(open(p, "rb").read())
        except (OSError, ValueError) as e:
            print(f"{os.path.basename(p)}: {e}")
            continue
        uprint(f"{os.path.basename(p)}: {describe_pk3(f)}")
        for prob in problems:
            print(f"  *** {prob} ***")


# ---------------------------------------------------------------- e-Reader trainers (.ect)
# A ".ect" is an e-Reader trainer as Ruby/Sapphire save it: the 0xBC-byte BattleTowerEReaderTrainer
# record, whose last word is the sum of the 46 before it (battle_tower.c). Like a .ecb, it's wrapped:
# checkcompat, checksum, addtrainer (command 13), end. The trainer then visits the old man's house
# in Mossdeep City.
MEV_ADDTRAINER = 13


def parse_ect(data):
    if len(data) != EREADER_TRAINER_SIZE:
        raise ValueError(f"not a saved e-Reader trainer: {len(data)} bytes, not {EREADER_TRAINER_SIZE}")
    words = struct.unpack("<47I", data)
    problems = []
    if not any(words[:46]):
        problems.append("the trainer record is empty")
    elif sum(words[:46]) & 0xFFFFFFFF != words[46]:
        problems.append(f"its checksum is {words[46]:#x}, but its words add up to {sum(words[:46]) & 0xFFFFFFFF:#x}")
    return dict(name=gen3_text(data[4:12])), problems


def build_trainer_script(rec, language="English", versions=("Ruby", "Sapphire")):
    lang_mask = MEV_LANGUAGE_MASKS[language]
    ver_mask = 0
    for v in versions:
        ver_mask |= MEV_VERSIONS[v]
    head_len = 17 + 13 + 5 + 1 + 0                # checkcompat, checksum, addtrainer, end
    start = MEV_BASE + head_len
    out = bytearray([MEV_CHECKCOMPAT]) + struct.pack("<IHIHI", MEV_BASE, lang_mask, lang_mask, 0x4, ver_mask)
    out += bytes([MEV_CHECKSUM]) + struct.pack("<iII", sum(rec), start, start + len(rec))
    out += bytes([MEV_ADDTRAINER]) + struct.pack("<I", start)
    out += bytes([MEV_END])
    assert len(out) == head_len
    return bytes(out + rec)


def describe_event_script(script):
    """Read a Mystery Event script's compatibility fields: (languages, versions, problems)."""
    if len(script) < 17 or script[0] != MEV_CHECKCOMPAT:
        return [], [], ["it doesn't start with checkcompat (command 1), so the game would store nothing"]
    _, l0, l1, flag, ver = struct.unpack_from("<IHIHI", script, 1)
    langs = [n for n, m in MEV_LANGUAGE_MASKS.items() if l0 & m and l1 & m]
    vers = [n for n, m in MEV_VERSIONS.items() if ver & m]
    problems = []
    if not flag & 0x4:
        problems.append("its compatibility flags lack 0x4, so every game would refuse it")
    if not langs:
        problems.append("it isn't marked for Japanese, English or German games")
    if not vers:
        problems.append("it isn't marked for Ruby or Sapphire")
    return langs, vers, problems


def prepare_event(data, path=""):
    """What to send for a file: (script, description, problems). Raises ValueError for files that
    are neither a Mystery Event script nor a saved Mystery Event (.me3)."""
    if data[:1] == bytes([MEV_CHECKCOMPAT]):
        if len(data) > MEV_MAX:
            raise ValueError(f"a Mystery Event script is at most {MEV_MAX} bytes (the game's buffer); this one is {len(data)}")
        langs, vers, problems = describe_event_script(data)
        return data, (f"a Mystery Event script for {'/'.join(vers) or 'no known version'}, "
                      f"{'/'.join(langs) or 'no known language'}"), problems
    language = file_language(path) or "English"
    if len(data) == EREADER_TRAINER_SIZE:
        trainer, problems = parse_ect(data)
        if language not in MEV_LANGUAGE_MASKS:
            raise ValueError(f"the trainer is for {language} games; Mystery Event scripts are only known for "
                             "Japanese, English and German Ruby/Sapphire")
        script = build_trainer_script(data, language)
        name = trainer["name"] if language != "Japanese" else "Japanese-named"
        text = (f"a saved e-Reader trainer (.ect): {name}; sent as a Mystery Event script for {language} games "
                f"that stores exactly it ({len(script)} bytes)")
        return script, text, problems
    if len(data) == ECB_SIZE:
        berry, problems = parse_ecb(data)
        if language not in MEV_LANGUAGE_MASKS:
            raise ValueError(f"the berry is for {language} games; Mystery Event scripts are only known for "
                             "Japanese, English and German Ruby/Sapphire")
        script = build_berry_script(data, language)
        if language == "Japanese":
            berry["name"] = "Japanese-named"                    # (the name is in Japanese characters)
        text = (f"a saved Enigma Berry (.ecb): the {berry['name']} BERRY ({', '.join(berry['flavours']) or 'no flavour'}); "
                f"sent as a Mystery Event script for {language} games that stores exactly it ({len(script)} bytes)")
        return script, text, problems
    me3, problems = parse_me3(data)
    if language not in MEV_LANGUAGE_MASKS:
        raise ValueError(f"the file is for {language} games; Mystery Event scripts are only known for "
                         "Japanese, English and German Ruby/Sapphire")
    script = build_event_script(me3, language)
    place = RS_PLACES.get((me3["map_group"], me3["map_num"]), f"map {me3['map_group']}.{me3['map_num']}")
    text = f"a saved Mystery Event (.me3): a script for person {me3['person']} in {place}"
    if me3["gift"]:
        item = me3["gift"][2]
        text += f", and a Record Mixing gift of item {item} ({RS_ITEMS.get(item, 'unknown')})"
    text += f"; sent as a Mystery Event script for {language} games that stores exactly these ({len(script)} bytes)"
    return script, text, problems


def prepare_card(path):
    """An e-Card (.raw), or several Japanese Emerald Trainer Hill cards: (data, description,
    problems, hint)."""
    paths = list(path) if isinstance(path, (list, tuple)) else [path]
    try:
        if len(paths) > 1:
            raise ValueError("several cards")
        script, names, langs, vers, problems = read_card(paths[0])
    except ValueError as err:
        if len(paths) == 1 and "Trainer Hill" not in str(err) and "no Mystery Event for Ruby" not in str(err):
            raise
        return prepare_hill_cards(paths)
    path = paths[0]
    if script is None:
        return None, "", problems, None
    strips = len(card_strip_paths(path))
    text = (f"an e-Card ({strips} strip{'s' if strips > 1 else ''}) for {'/'.join(vers) or 'no known version'}, "
            f"{'/'.join(langs) or 'no known language'}: its own Mystery Event, {' '.join(names)} "
            f"({len(script)} bytes), sent as the e-Reader sent it")
    return script, text, problems, card_hint(names)


def load_event(duo, path):
    """Hands the e-Reader program a Mystery Event script (0x2C PUT, then a CRC check)."""
    load_event.kind = "mystery event"
    if isinstance(path, (list, tuple)) or path.lower().endswith(".raw"):
        data, text, problems, hint = prepare_card(path)
        if hint in (HILL_HINT, TOWER_HINT):
            load_event.kind = "trainer hill" if hint == HILL_HINT else "trainer tower"
        path = path[0] if isinstance(path, (list, tuple)) else path
    else:
        raw = open(path, "rb").read()
        data, text, problems = prepare_event(raw, path)
        hint = event_hint(raw)
    for p in problems:
        print(f"  *** {os.path.basename(path)}: {p} ***")
    if problems:
        raise ValueError("the file failed its checks, so it wasn't sent")
    uprint(f"  {os.path.basename(path)}: {text}")          # (Trainer Hill names are in kana)
    # Ruby only runs a block that arrived in its big shared buffer, and its link layer puts only
    # blocks over 256 bytes there (link.c); a shorter one is "loaded" and does nothing. So every
    # event goes as the whole 2,004-byte buffer, the rest zeros (lab session 29).
    sent = data.ljust(MEV_MAX, b"\0")
    blob = len(sent).to_bytes(4, "little") + sent
    put_blob(duo, blob, "Mystery Event")
    if load_event.kind in ("trainer hill", "trainer tower"):
        print(f"  {load_event.kind.title()} set loaded ({len(data):,} bytes)")
    else:
        print(f"  Mystery Event loaded: {os.path.basename(path)} ({len(data)} bytes, sent as the game's full "
              f"{MEV_MAX:,}-byte buffer)")
    if hint:
        print(f"  Afterwards, in the game: {hint}.")
    return data, hint


def ereader_session(duo, args, poll_s=0.3, stop_when=None):
    """The DUO's GBA plays the Card e-Reader+ on the GBA link cable (docs/EREADER.md): it answers
    a Ruby/Sapphire (or Japanese Emerald) in its Mystery Event menu, and sends the event script.
    Nothing is written to either cartridge; the game saves the event itself."""
    seconds = getattr(args, "ereader", 600) or 600
    print("e-Reader on the link cable (reads and writes nothing on either cartridge)")
    run_program(duo, "ereader")
    event = hint = None
    if getattr(args, "mystery_event", None):
        try:
            event, hint = load_event(duo, args.mystery_event)
        except (OSError, ValueError, DuoError) as e:
            print(f"  Mystery Event not loaded ({e}); only link players will be exchanged (a dry run)")
    say_ready("event")
    finish = event is not None and not getattr(args, "keep_going", False)
    last, t0, report, session, warned, quiet_since = None, time.time(), {}, 0, False, None
    try:
        while time.time() - t0 < seconds:
            st = program_poll(duo, 0)
            state, master, sess = st & 0xF, st >> 4 & 1, st >> 5 & 7
            # the game closed the link and opened it again (for another event): start the story over
            if last is not None and (state < last or (session and sess != session and state <= last)):
                print(f"  [{time.time() - t0:6.1f} s] the game opened the link again")
                last = 0
            session = sess
            if last is None or state > last:
                # print every stage passed since the last poll, so the story is complete
                for s_ in range(0 if last is None else last + 1, state + 1):
                    if last is None and s_ < state and s_ < 2:
                        continue
                    text = EREADER_STATES[s_] if s_ < len(EREADER_STATES) else f"state {s_}"
                    if s_ == 2:
                        text += f" (the DUO is player {0 if master else 1})"
                        if master and not warned:
                            warned = True
                            text += ("\n  *** The DUO is on the master end of the cable, but Ruby/Sapphire's MYSTERY EVENT"
                                     "\n      menu only carries on when the game is the master (lab session 25). Switch"
                                     "\n      both GBAs off, swap the cable's ends, and start again. ***")
                    if s_ == 3:
                        v = program_poll(duo, 2)
                        lang = GAME_LANGUAGES.get(v >> 16, f"language {v >> 16}")
                        text += f": link type {v & 0xFFFF:#06x}, {lang}"
                        if event is not None and load_event.kind == "mystery event":
                            ev_langs = describe_event_script(event)[0]
                            if ev_langs and lang not in ev_langs:
                                text += (f"\n  *** The event is for {'/'.join(ev_langs)} games, so this {lang} game "
                                         "will say it can't be used. ***")
                        report["game_link_type"], report["game_language"] = v & 0xFFFF, v >> 16
                    print(f"  [{time.time() - t0:6.1f} s] {text}")
                last = state
            if stop_when and stop_when():
                break
            # finished once the game has closed the link AND gone quiet: "closed" is set when the
            # game's 0x5FFF arrives, before ours has gone out, and stopping then would leave the
            # game waiting for our half of the close
            if finish and state == len(EREADER_STATES) - 1:
                if quiet_since is None or quiet_since[1] != st >> 8:
                    quiet_since = (time.time(), st >> 8)
            else:
                quiet_since = None
            if quiet_since and time.time() - quiet_since[0] >= 1.0:
                print("  Finished: the game has received the event and closed the link. It now runs it and saves:")
                print("  wait for its message, then press A." + (f" After that: {hint}." if hint else ""))
                break
            time.sleep(poll_s)
    except KeyboardInterrupt:
        print("  Stopping (Ctrl+C)...")
    finally:
        extra = program_poll(duo, 1)
        diag = ereader_diagnostics(duo, extra & 0xFFFF)
        st = program_stop(duo)
    report.update(state=st & 0xFF, transfers=st >> 8, bad_checksums=extra & 0xFFFF, event=event, **diag)
    print(f"  Transfers: {st >> 8}, checksum mismatches: {extra & 0xFFFF}")
    if diag["events_sent"] > 1:
        print(f"  Mystery Events sent: {diag['events_sent']}")
    if extra & 0xFFFF:
        where = ", ".join(f"{EREADER_STATES[i]}: {n}" for i, n in enumerate(diag["mismatch_by_state"]) if n
                          and i < len(EREADER_STATES))
        print(f"  Where the mismatches were: {where}")
        for m in diag["mismatches"]:
            print(f"    at transfer {m['transfer']} ({EREADER_STATES[m['state']] if m['state'] < len(EREADER_STATES) else m['state']}):"
                  f" received {m['words'][0]:#06x} {m['words'][1]:#06x}, expected {m['expected']:#06x}")
    if diag["max_gap_lines"]:
        print(f"  Longest look away from the link while linked: {diag['max_gap_lines']} scanlines"
              f" (~{diag['max_gap_lines'] * 73} us)")
    ereader_session.last = report
    return report


# ---------------------------------------------------------------- trades: Stage 9 (docs/TRADE.md)
TRADE_STATES = ("waiting for the game", "handshaking", "linked", "in the Trade Center",
                "walking to the table", "seated: waiting for you to sit down too", "swapping parties",
                "at the trade menu", "chosen: waiting for your choice", "you said yes: trading",
                "the trade scene", "saving", "traded and saved", "leaving the trade screen",
                "no trade this time", "back to the Trade Center", "back in the room",
                "walking back to the door", "leaving the room", "done")
TRADE_ST = {name: i for i, name in enumerate(("WAITING", "HANDSHAKE", "CONNECTED", "ROOM", "WALKING", "SEATED",
            "PARTIES", "MENU", "CHOSEN", "AGREED", "SCENE", "SAVING", "TRADED", "LEAVING", "DECLINED",
            "RETURNING", "BACK", "WALKING_OUT", "EXITING", "DONE"))}
TRADE_NAME = bytes([0xBF, 0xD0, 0xBF, 0xC8, 0xCE, 0xFF, 0xFF, 0xFF])        # "EVENT", if the Pokemon has no OT


def build_trade_blob(pk3s, pick=0):
    """What the trade program is loaded with: party count, our pick, a trainer name and ID (the
    Pokemon's own trainer, as a distribution's partner), the party (game form, 100 bytes each),
    and empty mail."""
    party = [pk3_party_form(d) for d in pk3s]
    if not 1 <= len(party) <= 6:
        raise ValueError("a party is 1 to 6 Pokemon")
    first = pk3s[pick]
    name = first[0x14:0x1B] + b"\xFF" if any(b != 0xFF for b in first[0x14:0x1B]) else TRADE_NAME
    blob = bytes([len(party), pick, 0, 0]) + name[:8] + first[4:8]
    blob += b"".join(party).ljust(600, b"\0") + bytes(220)
    return blob + screen_line(f"Offering {parse_pk3(first)[0]['name']}")


def screen_line(text):
    """A line for the DUO's own screen: plain ASCII, at most 27 characters, in 28 bytes."""
    plain = "".join(c if " " <= c <= "~" else "?" for c in text)[:27]
    return plain.encode("ascii").ljust(28, b"\0")


