def trade_refusal(version, flags, f):
    """Why the game will refuse the event Pokemon `f` (parse_pk3), or None. version: the game's
    (1-5); flags: its link player's progress flags (Emerald/FireRed/LeafGreen: 0x0F National Dex).
    From pokeemerald/pokefirered trade.c CheckValidityOfTradeMons; Ruby and Sapphire check nothing."""
    game = GAME_VERSIONS.get(version, "this game")
    if version in (3, 4, 5) and f["dex"] in (151, 386) and not f["fateful"]:
        return (f"{game} only takes a {f['name'].title()} marked as a fateful encounter (an event one), "
                "and this file isn't marked")
    if version == 3 and not flags & 0x0F and (f["egg"] or f["dex"] not in HOENN_DEX):
        what = "an Egg" if f["egg"] else f"{f['name'].title()} (not in the Hoenn Pokedex)"
        return f"Emerald won't take {what} until it has the National Pokedex"
    return None


def traded_yet(duo):
    return bool(program_poll(duo, 3) >> 9 & 1)


def trade_session(duo, args, poll_s=0.3, stop_when=None):
    """The DUO's GBA plays the other player in a Cable Club Trade Center and trades the game one
    Pokemon (docs/TRADE.md). The game checks, shows, swaps and saves it itself; nothing is written
    to either cartridge by the DUO. What the game gives in return is kept as a .pk3."""
    path = args.pk3
    raw = open(path, "rb").read()
    f, problems = parse_pk3(raw)
    for p in problems:
        print(f"  *** {os.path.basename(path)}: {p} ***")
    if problems:
        raise ValueError("the file failed its checks, so it wasn't sent")
    uprint(f"  {os.path.basename(path)}: {describe_pk3(f)}")
    print("  A trade is one for one: offer a Pokemon you can spare. Whatever you give is kept on this PC.")
    seconds = getattr(args, "seconds", 900) or 900
    print("Trade partner on the link cable (reads and writes nothing on either cartridge)")
    run_program(duo, "trade")
    put_blob(duo, build_trade_blob([raw]), "trade")
    say_ready("trade")
    last, t0, report, stop_by = None, time.time(), {}, None
    try:
        while time.time() - t0 < seconds:
            st = program_poll(duo, 0)
            state, master = st & 0x1F, st >> 5 & 1
            if state != last:
                text = TRADE_STATES[state] if state < len(TRADE_STATES) else f"state {state}"
                if state == TRADE_ST["DECLINED"] and traded_yet(duo):
                    text = "leaving the trade screen"     # (after a trade, CANCEL is the way out)
                if state == TRADE_ST["ROOM"]:
                    v = program_poll(duo, 2)
                    version = program_poll(duo, 6) & 0xFF
                    flags = program_poll(duo, 7) & 0xFF
                    game = GAME_VERSIONS.get(version, f"version {version}")
                    dex = "" if version in (1, 2) else (", National Pokedex" if flags & 0x0F else ", no National Pokedex")
                    text += (f" (the DUO is player {0 if master else 1}; {GAME_LANGUAGES.get(v >> 16, 'language ' + str(v >> 16))} "
                             f"{game}{dex})")
                    refusal = trade_refusal(version, flags, f)
                print(f"  [{time.time() - t0:6.1f} s] {text}")
                if state == TRADE_ST["ROOM"] and refusal:
                    print(f"  *** {refusal}: it will say the Pokemon can't be traded. Choose CANCEL to leave. ***")
                last = state
            if stop_when and stop_when():             # (tests: the game has finished; let the DUO finish too)
                stop_by = stop_by or time.time() + 5
                if time.time() > stop_by:
                    break
            if state == TRADE_ST["DONE"]:
                time.sleep(1.0)                       # (our half of the close goes out)
                break
            time.sleep(poll_s)
    finally:
        info = program_poll(duo, 3)
        traded = bool(info >> 9 & 1)
        received = None
        if traded:
            words = [program_poll(duo, 5 | k << 8) for k in range(25)]
            received = b"".join(w.to_bytes(4, "little") for w in words)
        bad = program_poll(duo, 1)
        st = program_stop(duo)
        report.update(state=st & 0x1F, transfers=st >> 8, bad_checksums=bad & 0xFFFF, barriers=bad >> 16,
                      traded=traded, received=received)
    if received:
        rf, rp = parse_pk3(received)
        # beside the tools, never inside the event collection (lab session 29)
        out = RECEIVED_DIR or os.path.join(os.path.dirname(os.path.abspath(__file__)), "received")
        os.makedirs(out, exist_ok=True)
        name = os.path.join(out, f"{time.strftime('%Y-%m-%d %H%M%S')} {rf['name']} (for {f['name']}).pk3")
        open(name, "wb").write(received)
        uprint(f"  You gave: {describe_pk3(rf)}" + (f" ({'; '.join(rp)})" if rp else ""))
        print(f"  Kept on this PC: {name}")
        print("  Finished: the game has the event Pokemon and has saved.")
    else:
        print("  No trade was made." if report["state"] != TRADE_ST["DONE"] else "  Finished without a trade.")
    print(f"  Transfers: {report['transfers']}, checksum mismatches: {report['bad_checksums']}")
    trade_session.last = report
    return report


def ereader_diagnostics(duo, bad):
    """What the e-Reader program noted for the next look at a hardware run (lab sessions 24-25)."""
    by_state = [program_poll(duo, 7 | i << 8) & 0xFFFF for i in range(8)]
    mm = []
    for i in range(min(bad, 4)):
        info, words, expected = (program_poll(duo, k | i << 8) for k in (4, 5, 6))
        mm.append(dict(state=info & 0xFF, transfer=info >> 8, words=(words & 0xFFFF, words >> 16),
                       expected=expected & 0xFFFF))
    v = program_poll(duo, 8)
    return dict(mismatch_by_state=by_state, mismatches=mm, max_gap_lines=v & 0xFFFF, events_sent=v >> 16)


def connect(duo, wait_s, say=print):
    """Hello, then the firmware check. Seen on hardware (lab session 24): the very first try after
    switching on can time out with nothing said; a second try a little later works."""
    for attempt in range(2):
        try:
            version = duo.connect(wait_s=wait_s, say=say)
            return version, duo.can_run()
        except KeyboardInterrupt:
            raise
        except Exception as err:
            if attempt or not maxduo_saves._is_timeout(err):
                raise
            print(f"The DUO didn't finish answering; giving it {maxduo_saves.BUSY_WAIT_S} s, then trying again...")
            time.sleep(maxduo_saves.BUSY_WAIT_S)


