def uprint(text):
    """print, but never fail on a console that can't show Japanese (the romaji is there too)."""
    try:
        print(text)
    except UnicodeEncodeError:
        enc = getattr(sys.stdout, "encoding", None) or "ascii"
        print(text.encode(enc, "replace").decode(enc, "replace"))


def say_before(mode):
    print("Before you start: both GBAs should be switched off.")
    print(f"  Cable: {CABLES.get(mode, CABLES['gift'])}.")
    print("  Then switch on the DUO's GBA (the one with the Action Replay); leave the game's GBA off.")


def say_ready(mode):
    if mode == "probe":
        print("  Ready.")
    else:
        print("  Ready. Now switch on the game's GBA, then:")
    for line in MENUS.get(mode, []):
        uprint("    " + line)
    if mode in ("gift", "news", "probe"):
        print("  Every command the game sends the adapter is listed here.")


def file_games(path):
    """The games a community file's name says it's for ("E - ...", "FL - ...", "RS - ...")."""
    head = os.path.basename(path).split(" - ")[0].strip().upper()
    return {"E": ("Emerald",), "EM": ("Emerald",), "FL": ("FireRed", "LeafGreen"), "FRLG": ("FireRed", "LeafGreen"),
            "FR": ("FireRed", "LeafGreen"), "LG": ("FireRed", "LeafGreen"), "RS": ("Ruby", "Sapphire")}.get(head)


def connect_guided(duo, wait_s):
    def say(msg):
        if msg.startswith("The DUO isn't answering yet"):
            print("  Waiting for the DUO's GBA - switch it on now (it goes straight to USB SERVER MODE)...")
        else:
            print("  " + msg)
    t0 = time.time()
    version, v42 = connect(duo, wait_s, say)
    if time.time() - t0 < 1.5:
        print("  The DUO's GBA was already on: that's fine, as long as the game's GBA is still off.")
    return version, v42


# ---------------------------------------------------------------- the command line
def run(duo, args):
    mode = args.command
    if mode in ("gift", "news", "event", "trade", "probe", "adapter-test"):
        say_before("probe" if mode == "adapter-test" else mode)
        version, v42 = connect_guided(duo, args.wait)
    else:
        version, v42 = connect(duo, args.wait)
    print(f"Connected to Action Replay MAX DUO (Datel protocol {version >> 8}.{version & 0xFF:02d}"
          + (", Reckless v4.2)" if v42 else ")"))
    if mode == "find-serial":
        return find_serial_deep(duo) if args.deep else find_serial(duo)
    if mode == "event":
        return ereader_session(duo, argparse.Namespace(ereader=args.seconds, mystery_event=args.event,
                                                       keep_going=args.keep_going))
    if mode == "trade":
        return trade_session(duo, args)
    if mode == "adapter-test":
        return adapter_test(duo, argparse.Namespace(adapter_test=args.seconds))
    if mode == "probe":
        return adapter_trace(duo, argparse.Namespace(adapter_probe=args.seconds), program="adapter_probe")
    return adapter_trace(duo, argparse.Namespace(
        adapter_trace=args.seconds, wonder_card=getattr(args, "card", None), wonder_news=getattr(args, "news", None),
        check_search=getattr(args, "check_search", False), sweep_serial=getattr(args, "sweep_serial", False),
        serial=args.serial, keep_going=args.keep_going),
        program="adapter_lab" if getattr(args, "lab", False) else "adapter")


LEGACY = ("--test", "--trace", "--probe", "--find-serial", "--mystery-event", "--ereader", "--wonder-card",
          "--wonder-news", "--sweep-serial", "--check-search")


def translate_legacy(argv):
    """duo_wireless.py's flags (before 30 October 2026) -> duo_events.py's commands."""
    a, out, seconds = list(argv), [], None

    def take(flag, has_value=False, optional_int=False):
        nonlocal a
        if flag not in a:
            return None
        k = a.index(flag)
        val = True
        if has_value:
            val = a[k + 1]; del a[k:k + 2]
        elif optional_int and k + 1 < len(a) and a[k + 1].isdigit():
            val = a[k + 1]; del a[k:k + 2]
        else:
            del a[k]
        return val
    test, trace, probe = take("--test", optional_int=True), take("--trace", optional_int=True), take("--probe", optional_int=True)
    find, ereader = take("--find-serial"), take("--ereader", optional_int=True)
    event, card, news = take("--mystery-event", True), take("--wonder-card", True), take("--wonder-news", True)
    if find:
        out = ["find-serial"]
    elif event or ereader:
        out = ["event"] + (["--event", event] if event else [])
        seconds = ereader if ereader not in (None, True) else None
    elif test:
        out, seconds = ["adapter-test"], test if test is not True else None
    elif probe:
        out, seconds = ["probe"], probe if probe is not True else None
    elif news:
        out, seconds = ["news", "--news", news], trace if trace not in (None, True) else None
    else:
        out, seconds = ["gift"] + (["--card", card] if card else []), trace if trace not in (None, True) else None
    if seconds:
        out += ["--seconds", str(seconds)]
    return out + a


def parser():
    ap = argparse.ArgumentParser(
        prog="duo_events.py",
        description="Pokemon Generation III events from the Action Replay MAX DUO's GBA (firmware v4.2). "
                    "Reads and writes nothing on either cartridge: the game saves what it receives itself.",
        epilog="Examples:  duo_events.py gift --card \"E - Item Old Sea Map (JPN).wc3\"    "
               "duo_events.py event --event \"RS - Item Eon Ticket (ENG) (UK).me3\"")
    ap.add_argument("--wait", type=int, default=120, help="seconds to wait for the DUO's GBA to be switched on (default 120)")
    sub = ap.add_subparsers(dest="command", metavar="COMMAND")

    def common(p, seconds=600):
        p.add_argument("--seconds", type=int, default=seconds, help=f"stop after this long (default {seconds})")
        p.add_argument("--keep-going", action="store_true",
                       help="don't stop when the game has the gift: keep listening (Ctrl+C stops)")

    g = sub.add_parser("gift", help="Mystery Gift: a Wonder Card over the wireless adapter route (MGB-010 cable)")
    g.add_argument("--card", metavar="FILE.wc3", help="your own .wc3 file; without one, the distributor has nothing to send")
    g.add_argument("--serial", type=lambda x: int(x, 16) & 0x7FFF, metavar="HEX",
                   help="use this distributor serial instead of choosing one for the game (Japanese Emerald 7F7F, others 7F7D)")
    g.add_argument("--sweep-serial", action="store_true",
                   help="offer every distributor serial in turn until the game connects (about 6 minutes; a test)")
    g.add_argument("--check-search", action="store_true",
                   help="list the distributor four times per search answer: the game restarts its search if they arrive intact (a test)")
    g.add_argument("--lab", action="store_true", help="the lab build: flick tuning, a link-port scope, the first data commands")
    common(g)
    n = sub.add_parser("news", help="Mystery Gift: Wonder News over the wireless adapter route (MGB-010 cable)")
    n.add_argument("--news", metavar="FILE", required=True, help="your own Wonder News file (bare, or with its CRC in front)")
    n.add_argument("--serial", type=lambda x: int(x, 16) & 0x7FFF, metavar="HEX", help="as for gift")
    common(n)
    e = sub.add_parser("event", help="Mystery Event: the e-Reader route to Ruby/Sapphire (GBA link cable)")
    e.add_argument("--event", metavar="FILE", nargs="+", help="your own Mystery Event script or saved event (.me3); "
                   "several Japanese Emerald Trainer Hill e-Cards go together; without one, a dry run (link players only)")
    common(e)
    r = sub.add_parser("trade", help="a trade in the Cable Club: the game receives a Pokemon (.pk3) and saves it itself")
    r.add_argument("--pk3", metavar="FILE", required=True, help="the Pokemon to send (.pk3)")
    common(r)
    t = sub.add_parser("adapter-test", help="lab: does a game on the second GBA detect the adapter?")
    common(t, 180)
    p = sub.add_parser("probe", help="lab: the 2 MHz answer-encoding probe")
    common(p)
    k = sub.add_parser("pk3-info", help="read-only: describe Gen 3 Pokemon files (.pk3); no DUO needed")
    k.add_argument("files", nargs="+", metavar="FILE")
    f = sub.add_parser("find-serial", help="read-only: search the cartridge in the DUO for the distributor serial")
    f.add_argument("--deep", action="store_true", help="read the cartridge into memory and find the accepted-serials list")
    return ap


# Which command each kind of file goes with, so a file given to the wrong one is turned away
# before anything is sent (it once went ahead, and the game was told there was nothing to send).
FILE_ROUTES = {".wc3": "gift --card", ".wcn": "news --news", ".me3": "event --event", ".raw": "event --event",
               ".ecb": "event --event", ".ect": "event --event", ".pk3": "trade --pk3"}
ROUTE_WHAT = {"gift --card": "a Wonder Card, for Mystery Gift", "news --news": "Wonder News, for Mystery Gift",
              "event --event": "a Mystery Event, for Ruby/Sapphire's MYSTERY EVENT (the e-Reader route)",
              "trade --pk3": "a Pokemon, sent by trade"}


def wrong_route(command, path):
    """None if `path` suits `command`, else what to run instead."""
    if not path:
        return None
    ext = os.path.splitext(path)[1].lower()
    right = FILE_ROUTES.get(ext)
    given = {"gift": "gift --card", "news": "news --news", "event": "event --event", "trade": "trade --pk3"}.get(command)
    if right is None or given is None or right == given:
        return None
    return (f"{os.path.basename(path)} is {ROUTE_WHAT[right]}, not something `{command}` can send.\n"
            f"  Instead:  python duo_events.py {right} \"{path}\"")


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    if "--wait" in argv[1:]:                     # a global option: it goes before the command
        k = argv.index("--wait")
        argv = argv[k:k + 2] + argv[:k] + argv[k + 2:]
    if any(a in LEGACY for a in argv):
        new = translate_legacy(argv)
        print(f"(The old options still work. Next time: python duo_events.py {' '.join(new)})")
        argv = new
    ap = parser()
    args = ap.parse_args(argv)
    if not args.command:
        ap.print_help()
        return
    if args.command == "pk3-info":
        pk3_info(args.files)
        return
    given = getattr(args, {"gift": "card", "news": "news", "event": "event", "trade": "pk3"}.get(args.command, ""), None) \
        if args.command in ("gift", "news", "event", "trade") else None
    if isinstance(given, list):                  # (event --event takes several Trainer Hill cards)
        if len(given) == 1:
            args.event = given = given[0]
        else:
            given = given[0]
    instead = wrong_route(args.command, given)
    if instead:
        sys.exit(instead)
    for name in ("serial", "keep_going"):
        if not hasattr(args, name):
            setattr(args, name, None if name == "serial" else False)
    t = UsbTransport()
    try:
        run(MaxDuo(t), args)
    except DuoError as err:
        sys.exit(f"\nStopped: {err}")
    except Exception as err:
        if type(err).__name__ in ("USBTimeoutError", "USBError"):
            sys.exit(f"\nThe Action Replay stopped answering ({err}).\n"
                     "Check the console batteries and that USB SERVER MODE is still showing.")
        raise
    finally:
        t.close()


if __name__ == "__main__":
    main()
